// The office code for a 4-letter issuing-office id (KOKX → OKX, PAFC → AFC,
// TJSJ → SJU, NSTU → PPG), or null for anything that is not a forecast
// office Plaincast knows (KWBC, a national center, is null). Case- and
// whitespace-tolerant; never throws.
export function officeCodeFromIssuing(id) {
    const key = String(id ?? '').trim().toUpperCase();
    return Object.hasOwn(ISSUING_OFFICE_TO_CODE, key) ? ISSUING_OFFICE_TO_CODE[key] : null;
}

// The office that issued an NWS alert, from its WMO heading
// (properties.parameters.WMOidentifier, e.g. "WWUS81 KOKX 181200" → OKX).
// Alaska alerts carry ZONE codes in their AWIPS id (WSWALU, WSWAER), but the
// heading always names the issuing office (PAFC → AFC). Null when absent.
export function alertOfficeCode(props) {
    const wmo = props?.parameters?.WMOidentifier;
    const heading = String((Array.isArray(wmo) ? wmo[0] : wmo) ?? '');
    return officeCodeFromIssuing(heading.trim().split(/\s+/)[1]);
}

